/// <summary>
/// AVAPurchTableApproveCls for updating AVAApproved in purchTable record sets
/// </summary>
class AVAPurchTableApproveCls
{
    FormDataSource purchTable_fds;
    Args args;

}

Method.Source:
/// <summary>
/// Checks if all selected purchTable records are approved and updates to the correct value
/// </summary>
public void approveOrders()
{
    PurchTable purchTable = purchTable_fds.getFirst(true);
    NoYes updateValue = NoYes::No;

    while(purchTable)
    {
        if(purchTable.AVAApproved == NoYes::No)
        {
            updateValue = NoYes::Yes;
            break;
        }

        purchTable = purchTable_fds.getNext();
    }

    this.updatePurchTableApprove(updateValue);
}

/// <summary>
/// updates the field AVAApproved for all selected PurchTable records with provided value
/// </summary>
/// <param name = "_updateValue">NoYes</param>
public void updatePurchTableApprove(NoYes _updateValue)
{
    PurchTable purchTable = purchTable_fds.getFirst(true);

    ttsbegin;

    while(purchTable)
    {
        purchTable.selectForUpdate(true);
        purchTable.AVAApproved = _updateValue;
        purchTable.doUpdate();

        purchTable = purchTable_fds.getNext();
    }

    ttscommit;

    purchTable_fds.research(true);
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVAPurchTableApproveCls  controller;
    controller = AVAPurchTableApproveCls::newFromArgs(_args);

    controller.approveOrders();
}

/// <summary>
/// parm method for PurchTable FormDataSource
/// </summary>
/// <param name = "_fds">FormDataSource</param>
/// <returns>FormDataSource</returns>
public FormDataSource parmCallerFormDataSource(FormDataSource _fds = purchTable_fds)
{
    purchTable_fds = _fds;
    return purchTable_fds;
}

/// <summary>
/// parmArgs method
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>Args</returns>
public Args parmArgs(Args _args = args)
{
    args = _args;

    return args;
}

/// <summary>
///     Creates an instance of the <c>AVAPurchTableApproveCls</c> class.
/// </summary>
/// <param name="_args">
///    The arguments of the <c>AVAPurchTableApproveCls</c> class.
/// </param>
/// <returns>
///     An instance of the <c>AVAPurchTableApproveCls</c> class.
/// </returns>
public static AVAPurchTableApproveCls newFromArgs(Args _args)
{
    AVAPurchTableApproveCls  controller;

    controller = new AVAPurchTableApproveCls();
    controller.parmArgs(_args);
    controller.parmCallerFormDataSource(FormDataUtil::getFormDataSource(_args.record()));

    return controller;
}
